$border-color: #d4d6c7 !default;
$font-family-sans-serif: "Source Serif 4", Georgia, serif !default;
$font-family-monospace: "IBM Plex Mono", monospace !default;
$headings-font-weight: 400 !default;
$font-size-root: 16px !default;
$font-size-base: 1.25rem !default;
$line-height-base: 1.6 !default;
$navbar-bg: #f8f4eb !default;
$navbar-fg: #25372d !default;
